package com.silverguardian.prototype.modules;
import com.silverguardian.prototype.data.Repository;import com.silverguardian.prototype.models.*;import java.util.*;
public class MedicineReminderModule{public static final String ALL_TYPES="ALL_TYPES";private final Repository r;public MedicineReminderModule(Repository r){this.r=r;}public List<Medicine>getMedicines(){return new ArrayList<>(r.getMedicines());}public List<Medicine>getMedicines(String t){List<Medicine>x=new ArrayList<>();for(Medicine m:r.getMedicines())if(t==null||t.isEmpty()||ALL_TYPES.equals(t)||t.equals(m.type))x.add(m);return x;}public int getTakenCount(){int n=0;for(Medicine m:r.getMedicines())if(m.takenToday)n++;return n;}public List<String>getMedicineTypes(){return new ArrayList<>(r.medicineTypes());}public List<MedicineLibraryItem>searchMedicineLibrary(String k){return r.searchMedicineLibrary(k);}public Medicine addMedicine(String n,String t,String time,String method,String d){return r.addMedicine(n,t,time,method,d);}public Medicine addMedicine(String n,String t,String time,String method,String d,int a,int rc,int ri){return r.addMedicine(n,t,time,method,d,a,rc,ri);}public void addLibraryItem(MedicineLibraryItem i){r.addLibraryItem(i);}public void updateLibraryItem(MedicineLibraryItem i){r.updateLibraryItem(i);}public void deleteLibraryItem(MedicineLibraryItem i){r.deleteLibraryItem(i);}public void toggleMedicineTaken(Medicine m,boolean b){r.toggleMedicineTaken(m,b);}public void deleteMedicine(Medicine m){r.deleteMedicine(m);}}